\section{Introduction}

Two classical objects meet in this paper. The \emph{Berggren tree}, described by
B.~Berggren in 1934 and rediscovered many times since, exhibits the primitive
Pythagorean triples as an infinite ternary tree rooted at $(3,4,5)$: three fixed
integer matrices generate every primitive triple exactly once. The \emph{Poincar\'e
upper half-plane} $\HH=\{z\in\mathbb{C}:\Ima z>0\}$ with metric $ds=|dz|/\Ima z$ is
the standard model of the hyperbolic plane; its ideal boundary is
$\mathbb{R}\cup\{\infty\}$, its geodesics are the vertical half-lines and the
semicircles orthogonal to $\mathbb{R}$, and its distance obeys
\begin{equation}\label{eq:dist}
\cosh d_{\HH}(z,w) \;=\; 1+\frac{|z-w|^2}{2\,\Ima z\,\Ima w}.
\end{equation}

The bridge is Euclid's parametrisation, which turns a triple into a pair of integers
and hence into a point of $\HH$. The resulting picture is startlingly organised:
straight lines fan out from the ideal points $0$ and $1$, further fans appear at
$0.5$, $0.333\ldots$ and $0.2$, and a single ray marches away from the base point in
even strides. We prove that every feature of that picture is a theorem, and in
particular answer three questions raised by looking at it. \emph{Which rationals
carry fans?} All of them (Section~\ref{sec:charge}). \emph{Why are some fans half
empty?} Because of a parity obstruction depending only on the parity of $p+q$
(Sections~\ref{sec:quant}--\ref{sec:real}). \emph{Why does the eye see only a
handful of fans?} Because the ray spacing of the fan at $p/q$ is $y/q$ at plot
height $y$, so the visible centres are the Farey fractions of a level fixed by the
resolution (Section~\ref{sec:vis}).

\section{The embedding}

\begin{definition}[Euclid seed]
A pair $(m,n)$ of positive integers is a \emph{Euclid seed} if $0<n<m$,
$\gcd(m,n)=1$ and $m+n$ is odd.
\end{definition}

The map $(m,n)\mapsto(m^2-n^2,2mn,m^2+n^2)$ is a bijection from Euclid seeds onto
primitive Pythagorean triples with the even leg listed second. We write
$c=c(m,n)=m^2+n^2$ for the \emph{hypotenuse} and $t=n/m\in(0,1)$ for the
\emph{slope}. The root seed is $(2,1)$, giving $(3,4,5)$.

\begin{definition}[Berggren moves]
$B_1(m,n)=(2m-n,\,m)$, \quad $B_2(m,n)=(2m+n,\,m)$, \quad $B_3(m,n)=(m+2n,\,n)$.
\end{definition}

\begin{proposition}
Each move carries Euclid seeds to Euclid seeds.
\end{proposition}

\begin{proof}
Positivity and $n'<m'$ follow from $0<n<m$. A common divisor of $2m-n$ and $m$
divides $n$ and hence divides $\gcd(m,n)=1$; the other two moves are identical in
this respect. Each move changes the coordinate sum by an even amount, so the oddness
of $m+n$ persists.
\end{proof}

Berggren's theorem asserts that iterating the three moves from $(2,1)$ produces every
Euclid seed exactly once. The proof is a descent: a seed $(M,N)\ne(2,1)$ has parent
$(M-2N,N)$ if $M>3N$, $(N,M-2N)$ if $2N<M\le 3N$, and $(N,2N-M)$ if $M\le 2N$; the
first coordinate strictly decreases, and the degenerate cases $M=2N$, $M=3N$ are
excluded by coprimality and parity.

\begin{definition}
For a Euclid seed put $z(m,n)=(n+i)/m = n/m + i/m \in\HH$, with base point $i$. Since
$\Ima z = 1/m$ recovers $m$ and $\Rea z = n/m$ then recovers $n$, the embedding is
injective.
\end{definition}

\begin{theorem}[Radial law]\label{thm:radial}
For all $m\ge1$, $n\ge0$,
\[
\cosh d_{\HH}\big(i,z(m,n)\big) \;=\; \frac{m^2+n^2+1}{2m} \;=\; \frac{c+1}{2m}.
\]
\end{theorem}

\begin{proof}
Apply \eqref{eq:dist} with $z=i$, $w=(n+i)/m$: here $\Ima w = 1/m$ and
$|z-w|^2 = (n^2+(m-1)^2)/m^2$, so
$\cosh d = 1+\tfrac{m}{2}(n^2+(m-1)^2)/m^2 = (m^2+n^2+1)/(2m)$.
\end{proof}

\begin{corollary}[Trajectory window]\label{cor:window}
$\tfrac12\log c \le d_{\HH}(i,z(m,n)) \le \tfrac12\log(2(c+1))$, so the radius of a
node is $\tfrac12\log c$ up to an additive error confined to
$[0,\tfrac12\log 2 + 1/2c]$.
\end{corollary}

\begin{proof}
$\cosh(\tfrac12\log c)=(c+1)/(2\sqrt c)$, so the lower bound is $m\le\sqrt c$, i.e.
$m^2\le m^2+n^2$. For the upper bound, $\cosh d\le e^d\le 2\cosh d$ gives
$d\le\log((c+1)/m)$, and $n<m$ forces $2m^2\ge c+1$, whence
$(c+1)/m\le\sqrt{2(c+1)}$.
\end{proof}

A \emph{hypercycle} is a curve of constant hyperbolic distance from a geodesic. In
the half-plane the geodesic joining a real point $x$ to $\infty$ is the vertical ray
$\gamma_x=\{x+is: s>0\}$, and its hypercycles are the Euclidean rays emanating
from~$x$.

\begin{theorem}[Hypercycle theorem]\label{thm:hyp}
Let $z\in\HH$ satisfy $x-\Rea z = \lambda\,\Ima z$ for a real $\lambda$. Then
$d_{\HH}(z,\gamma_x)=\arsinh|\lambda|$, attained at the point of $\gamma_x$ of height
$\Ima(z)\sqrt{1+\lambda^2}$.
\end{theorem}

\begin{proof}
With $y=\Ima z$ and $w=x+is$, \eqref{eq:dist} gives
\[
\cosh d(z,w) = \frac{(\Rea z-x)^2+y^2+s^2}{2ys}
= \frac{(1+\lambda^2)y^2+s^2}{2ys} \;\ge\; \sqrt{1+\lambda^2}
\]
by the arithmetic--geometric mean inequality, with equality exactly at
$s=y\sqrt{1+\lambda^2}$. Since $\arcosh\sqrt{1+\lambda^2}=\arsinh|\lambda|$, the
claim follows.
\end{proof}

\section{The charge at a rational ideal point}\label{sec:charge}

\begin{definition}[Charge]
Let $p/q$ be a rational in lowest terms with $q\ge1$. The \emph{charge} of the
integral pair $(m,n)$ at $p/q$ is $\chg{p/q}(m,n)= pm-qn$.
\end{definition}

Two special cases are the classical ones: $\chg{0/1}(m,n)=-n$ and
$\chg{1/1}(m,n)=m-n$, recovering the two conspicuous stars at the ideal points $0$
and~$1$.

\begin{theorem}[Ray identity]\label{thm:ray}
For every $m\ge1$, $n\ge0$,
\[
\frac{p}{q}-\Rea z(m,n) \;=\; \frac{\chg{p/q}(m,n)}{q}\cdot\Ima z(m,n).
\]
Hence the nodes of a fixed charge $k$ at $p/q$ all lie on the single Euclidean ray
through $p/q$ of parameter $k/q$.
\end{theorem}

\begin{proof}
$\dfrac{p}{q}-\dfrac{n}{m}=\dfrac{pm-qn}{qm}=\dfrac{\chg{p/q}(m,n)}{q}\cdot\dfrac1m$.
\end{proof}

\begin{theorem}[The rays are hypercycles]\label{thm:hypray}
For every seed $(m,n)$,
\[
d_{\HH}\big(z(m,n),\gamma_{p/q}\big) \;=\; \arsinh\frac{|\chg{p/q}(m,n)|}{q}.
\]
The distance depends on the node only through the charge; the star at $p/q$ is a
discrete pencil of hypercycles at the quantised levels $\arsinh(k/q)$, $k\in\ZZ$.
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:ray} and~\ref{thm:hyp} with $\lambda=\chg{p/q}(m,n)/q$.
\end{proof}

\begin{corollary}\label{cor:visgap}
Every node off the axis of the star at $p/q$ lies at distance at least $\arsinh(1/q)$
from that axis, and the sub-fan of charges $|k|\le K$ is confined to a band of
hyperbolic width $\arsinh(K/q)$. The lower bound is attained: the seed $(3,2)$
realises the level $\arsinh(1/2)$ at the star $1/2$. Since $q\mapsto\arsinh(1/q)$ is
strictly decreasing, a star of large denominator is squeezed into a thin pencil.
\end{corollary}

\section{Quantisation: which rays can carry nodes}\label{sec:quant}

\begin{theorem}[Parity quantisation]\label{thm:parity}
Suppose $p$ and $q$ are both odd, equivalently $p+q$ is even. Then every Euclid seed
has \emph{odd} charge at $p/q$, so half the rays of that pencil are empty.
\end{theorem}

\begin{proof}
Since $m+n$ is odd, exactly one of $m,n$ is even. If $m$ is even then $pm$ is even
and $qn$ is odd; if $m$ is odd then $pm$ is odd and $qn$ is even. In both cases
$pm-qn$ is odd.
\end{proof}

For $p=q=1$ this is the classical statement that the $1$-star realises only the odd
parameters $u=m-n$; the theorem shows the phenomenon is shared by $1/3$, $1/5$,
$3/5$, $3/7$, and every other centre with both entries odd.

\begin{example}
No Euclid seed has charge $2$ at $1/3$: the ray of parameter $2/3$ from the ideal
point $1/3$ is entirely empty, as is every even ray of that fan.
\end{example}

\begin{theorem}[The axis carries at most one node]\label{thm:axis}
Let $q>0$, $\gcd(p,q)=1$, and let $(m,n)$ be a Euclid seed. Then
$\chg{p/q}(m,n)=0$ if and only if $(m,n)=(q,p)$.
\end{theorem}

\begin{proof}
$\chi=0$ says $pm=qn$. Since $\gcd(p,q)=1$ we get $q\mid m$; since $m\mid qn$ and
$\gcd(m,n)=1$ we get $m\mid q$. Hence $m=q$, and cancelling $m$ in $mp=mn$ gives
$n=p$. The converse is the computation $pq-qp=0$.
\end{proof}

\begin{theorem}[Axis dichotomy]\label{thm:axisdich}
For coprime $0<p<q$, the axis of the star at $p/q$ carries a node if and only if
$p+q$ is odd.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:axis} the only candidate is $(q,p)$, which satisfies $0<p<q$ and
$\gcd(q,p)=1$; it is a Euclid seed precisely when $q+p$ is odd.
\end{proof}

\begin{example}
The stars at $1/2$, $1/4$, $2/5$ have a node exactly on their centre line; those at
$1/3$, $1/5$, $3/5$ have a hole along the axis. The axis node of the star at $1/2$ is
the seed $(2,1)$ --- the root of the entire tree, the triple $(3,4,5)$.
\end{example}

\section{Realisation: every admissible ray is infinite}\label{sec:real}

\begin{definition}[Ray parametrisation]
Let $\gcd(p,q)=1$ and choose $a,b\in\ZZ$ with $pb-qa=1$. For a charge $k$ and a
parameter $s\in\ZZ$ set $\Sigma(k,s)=(kb+sq,\ ka+sp)$.
\end{definition}

\begin{proposition}[Dictionary]\label{prop:dict}
For all $k,s$: \emph{(1)} $\chg{p/q}(\Sigma(k,s))=k$, identically in $s$;
\emph{(2)} $s=bn-am$, so $\Sigma$ is a bijection of $\ZZ^2$ onto $\ZZ^2$;
\emph{(3)} $m+n=k(a+b)+s(p+q)$; \emph{(4)} $\gcd(k,s)=1$ if and only if
$\gcd(m,n)=1$.
\end{proposition}

\begin{proof}
(1) $p(kb+sq)-q(ka+sp)=k(pb-qa)=k$. (2) $b(ka+sp)-a(kb+sq)=s(pb-qa)=s$. (3) Immediate.
(4) The substitution has determinant $pb-qa=1$, so it is invertible over $\ZZ$; a
B\'ezout relation for $(k,s)$ transports to one for $(m,n)$ through (1) and (2), and
conversely.
\end{proof}

Item (4) is the crux: the arithmetic of the node is transported verbatim to the
arithmetic of the pair (charge, parameter).

\begin{theorem}[Realisation]\label{thm:realise}
Let $0<p<q$ be coprime and let $k\ne0$ be an integer, required to be odd when $p+q$
is even. Then for every bound $M$ there is a Euclid seed $(m,n)$ with $m>M$ and
$\chg{p/q}(m,n)=k$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $\Sigma(k,s)$ and choose $s$ in a suitable residue class modulo $2$, fixing the
parity of $m+n$ by Proposition~\ref{prop:dict}(3), and coprime to $k$, securing
$\gcd(m,n)=1$ by \ref{prop:dict}(4). If $p+q$ is odd the parity of $m+n$ can be
switched freely by moving $s$ by $1$; if $p+q$ is even the parity of $m+n$ equals
that of $k(a+b)$, and $pb-qa=1$ with $p,q$ odd forces $a+b$ odd, so odd $k$ gives
odd $m+n$ as required. Taking $s$ large makes $m=kb+sq$ exceed $M$, and $0<n<m$ holds
for all large $s$ because $0<p<q$.
\end{proof}

\begin{corollary}
Under the hypotheses of Theorem~\ref{thm:realise}, the set of Euclid seeds of charge
$k$ at $p/q$ is infinite.
\end{corollary}

\begin{theorem}[The exact fan]\label{thm:fan}
For coprime $0<p<q$,
\[
\big\{\chg{p/q}(m,n) : (m,n)\ \text{a Euclid seed}\big\}
=\begin{cases}
\ZZ, & p+q\ \text{odd},\\
\{k\in\ZZ : k\ \text{odd}\}, & p+q\ \text{even}.
\end{cases}
\]
\end{theorem}

\begin{proof}
If $p+q$ is odd, charge $0$ is realised by the axis node of
Theorem~\ref{thm:axisdich} and every $k\ne0$ by Theorem~\ref{thm:realise}. If $p+q$
is even, only odd charges occur by Theorem~\ref{thm:parity} and every odd charge
occurs by Theorem~\ref{thm:realise}.
\end{proof}

Theorem~\ref{thm:fan} is the complete description of a fan. The picture contains
exactly two kinds of star: \emph{full} stars, with a node on the axis and a ray at
every integer level, and \emph{half} stars, with an empty axis and rays only at the
odd levels. The type is read off from the parity of $p+q$.

\section{How densely a ray is populated: a totient law}

\begin{theorem}[Coprimality is the only obstruction]\label{thm:onlycop}
Let $0<p<q$ be coprime with $p,q$ both odd, let $k$ be an odd charge, and let $a,b$
satisfy $pb-qa=1$. Then for all parameters $s$ beyond the explicit bound
$|ka|+|kb|+|k(b-a)|+1$, the pair $\Sigma(k,s)$ is a Euclid seed if and only if
$\gcd(|k|,s)=1$.
\end{theorem}

\begin{proof}[Proof sketch]
Beyond the bound the inequalities $0<ka+sp<kb+sq$ hold, because $0<p<q$ makes both
$sp$ and $s(q-p)$ dominate the constant terms. Coprimality of the pair is equivalent
to $\gcd(k,s)=1$ by Proposition~\ref{prop:dict}(4). Parity is automatic: $p+q$ is
even and $pb-qa=1$ with $p,q$ odd forces $b-a$, hence $a+b$, odd; so
$m+n=k(a+b)+s(p+q)$ is odd for odd $k$, independently of $s$.
\end{proof}

\begin{theorem}[Window counts]\label{thm:windows}
For all $K\ge1$ and $N\ge0$:
\begin{enumerate}
\item $\#\{s\in[N,N+2K) : \gcd(K,s)=1\}=2\varphi(K)$;
\item $\#\{s\in[N,N+2K) : \gcd(K,s)=1,\ s\ \text{odd}\}=\varphi(2K)$;
\item $\#\{s\in[N,N+2K) : \gcd(K,s)=1,\ s\ \text{even}\}=2\varphi(K)-\varphi(2K)$;
\item if $K$ is odd, both parity classes contain exactly $\varphi(K)$ parameters.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) Split the window into two windows of length $K$; coprimality to $K$ is periodic
modulo $K$ and one full period contains $\varphi(K)$ such integers. (2)
$\gcd(2K,s)=1$ if and only if $\gcd(K,s)=1$ and $s$ is odd, and a window of length
$2K$ is one full period of the modulus $2K$. (3) Subtract (2) from (1). (4) For odd
$K$, multiplicativity gives $\varphi(2K)=\varphi(2)\varphi(K)=\varphi(K)$, and then
(3) also yields $\varphi(K)$.
\end{proof}

\begin{theorem}[Totient density law]\label{thm:density}
Let $0<p<q$ be coprime with $p,q$ both odd, let $k$ be an odd charge and $K=|k|$.
Then in every window of $2K$ consecutive parameters beyond the bound of
Theorem~\ref{thm:onlycop}, the ray of charge $k$ at $p/q$ carries exactly
$2\varphi(K)=2\varphi(2K)$ nodes. The ray is infinite but of arithmetic density
$\varphi(K)/K$ in its parameter.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:onlycop} the seed condition on the window coincides with
$\gcd(K,s)=1$; apply Theorem~\ref{thm:windows}(1).
\end{proof}

\begin{example}
On the ray of charge $15$ at $1/3$, exactly $2\varphi(15)=16$ of every $30$
consecutive parameters give nodes: density $8/15$. On the ray of charge $5$ the
density is $4/5$; on the innermost ray, charge $1$, it is~$1$. Counting seeds with
$m\le 20000$ confirms the predicted densities $1.0000$, $0.6666$ and $0.8000$ at
$(p/q,k)=(1/3,1)$, $(1/3,3)$ and $(1/5,5)$ respectively.
\end{example}

\section{Diophantine meaning: Farey neighbours}

\begin{theorem}[Approximation dictionary]\label{thm:approx}
For $q,m\ge1$,
$\dfrac{n}{m}-\dfrac{p}{q}=-\dfrac{\chg{p/q}(m,n)}{qm}$, and consequently, for every
real $K$,
\[
\Big|\frac{n}{m}-\frac{p}{q}\Big|\le\frac{K}{qm}
\iff \big|\chg{p/q}(m,n)\big|\le K .
\]
\end{theorem}

\begin{proof}
$\dfrac{n}{m}-\dfrac{p}{q}=\dfrac{qn-pm}{qm}=-\dfrac{\chi}{qm}$; divide by $qm>0$.
\end{proof}

\begin{theorem}[Farey]\label{thm:farey}
Let $q,m,s>0$ with $qn-pm=1$. If $r/s$ lies strictly between $p/q$ and $n/m$ then
$s\ge q+m$.
\end{theorem}

\begin{proof}
Unimodularity gives $n/m-p/q=1/(qm)$. From $p/q<r/s<n/m$ we obtain the integer
inequalities $rq-ps\ge1$ and $ns-rm\ge1$, so
\[
\frac{1}{qm}=\Big(\frac{n}{m}-\frac{r}{s}\Big)+\Big(\frac{r}{s}-\frac{p}{q}\Big)
=\frac{ns-rm}{ms}+\frac{rq-ps}{qs}\ \ge\ \frac1{ms}+\frac1{qs},
\]
and multiplying by $qms>0$ yields $s\ge q+m$.
\end{proof}

\begin{theorem}[Sharpness]
Under $qn-pm=1$ the mediant $(p+n)/(q+m)$ lies strictly between $p/q$ and $n/m$, so
the bound $q+m$ is attained.
\end{theorem}

\begin{proof}
$\dfrac{p+n}{q+m}-\dfrac{p}{q}=\dfrac{qn-pm}{q(q+m)}>0$ and
$\dfrac{n}{m}-\dfrac{p+n}{q+m}=\dfrac{qn-pm}{m(q+m)}>0$.
\end{proof}

\begin{corollary}
A node of charge $-1$ at $p/q$ has slope differing from $p/q$ by exactly $1/(qm)$,
and no rational of denominator smaller than $q+m$ lies strictly between $p/q$ and
that slope: the nodes of the innermost ray are best approximations to the star
centre.
\end{corollary}

\begin{theorem}[Two principal stars]\label{thm:two}
Every Euclid seed $(m,n)$ with $m\ge2$ lies on the innermost ray of two distinct
stars of denominator smaller than $m$: there are $(p,q)$ and $(p',q')$ with
$0<q,q'<m$, $\chg{p/q}(m,n)=-1$ and $\chg{p'/q'}(m,n)=+1$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $\gcd(m,n)=1$, reduce a B\'ezout coefficient modulo $m$ to obtain $q\in(0,m)$
with $qn\equiv1\pmod m$, and put $p=(qn-1)/m$; then $qn-pm=1$, i.e. the charge at
$p/q$ is $-1$. Taking $q'=m-q\in(0,m)$ gives $q'n\equiv-1\pmod m$, and
$p'=(q'n+1)/m$ satisfies $p'm-q'n=1$. The two star parameters differ because the
charges do.
\end{proof}

\section{Visibility: why only a few fans are seen}\label{sec:vis}

\begin{theorem}[Separation at a fixed height]
Two nodes at the same height $y=1/m$ whose charges at $p/q$ differ by $d$ are
separated in the real part by exactly $|d|/(qm)=|d|\,y/q$.
\end{theorem}

\begin{proof}
$\Rea z(m,n)-\Rea z(m,n')=(n-n')/m$ and
$\chg{p/q}(m,n)-\chg{p/q}(m,n')=-q(n-n')$.
\end{proof}

\begin{corollary}
At plot height $y$, adjacent rays of the star at $p/q$ --- charges $k$ and $k+1$ ---
are exactly $y/q$ apart.
\end{corollary}

\begin{theorem}[Resolution criterion]\label{thm:res}
Fix a plot height $y>0$ and a resolution $\varepsilon>0$. The star at $p/q$ is
resolved --- adjacent rays at least $\varepsilon$ apart --- if and only if
$q\le y/\varepsilon$.
\end{theorem}

\begin{proof}
$\varepsilon\le y/q \iff q\varepsilon\le y \iff q\le y/\varepsilon$, all quantities
being positive.
\end{proof}

\begin{definition}
For $Q\ge1$ let $\mathcal{F}(Q)$ be the set of star centres $p/q\in(0,1]$ in lowest
terms with $q\le Q$.
\end{definition}

\begin{theorem}[Farey count]\label{thm:fareycount}
$\#\mathcal{F}(Q)=\sum_{q=1}^{Q}\varphi(q)$.
\end{theorem}

\begin{proof}
For each $q\le Q$ the admissible numerators are the $p\in[1,q]$ coprime to $q$, of
which there are $\varphi(q)$; distinct denominators contribute disjoint sets of
fractions in lowest terms.
\end{proof}

\begin{corollary}[Visibility law]
At plot height $y$ and resolution $\varepsilon$, the resolvable star centres in
$(0,1]$ are exactly $\mathcal{F}(Q)$ with $Q=\lfloor y/\varepsilon\rfloor$, a finite
set of cardinality $\sum_{q\le Q}\varphi(q)$.
\end{corollary}

\begin{example}
At $y=1/2$ and resolution one part in ten, $Q=5$ and the resolvable centres are the
ten fractions $\tfrac11,\tfrac12,\tfrac13,\tfrac23,\tfrac14,\tfrac34,\tfrac15,
\tfrac25,\tfrac35,\tfrac45$, together with the centre $0$ --- precisely the fans a
rendering at that scale displays. Sharpening the resolution by a factor $2$ takes $Q$
to $10$ and the count to $32$; by a factor $10$ it takes $Q$ to $50$ and the count to
$774$. Empirically $\sum_{q\le Q}\varphi(q)/Q^2$ equals $0.3200$, $0.3096$, $0.3044$,
$0.3045$ at $Q=10,50,100,500$, consistent with $3/\pi^2=0.303964\ldots$
\end{example}

\section{Star transport: the tree permutes the fans}

\begin{definition}[Transport]
$T_1(p,q)=(2p-q,\,p)$, \quad $T_2(p,q)=(2p-q,\,-p)$, \quad $T_3(p,q)=(p,\,q-2p)$.
\end{definition}

\begin{theorem}[Covariance]\label{thm:cov}
For each $i\in\{1,2,3\}$ and all integral $(p,q)$ and $(m,n)$,
$\chg{(p,q)}\big(B_i(m,n)\big)=\chg{T_i(p,q)}(m,n)$, where $\chg{(p,q)}(m,n)$
denotes $pm-qn$ for a not necessarily reduced parameter.
\end{theorem}

\begin{proof}
Three identities: $p(2m-n)-qm=(2p-q)m-pn$; $p(2m+n)-qm=(2p-q)m-(-p)n$; and
$p(m+2n)-qn=pm-(q-2p)n$.
\end{proof}

\begin{theorem}[Transport preserves primitivity]
If $\gcd(p,q)=1$ then the entries of $T_i(p,q)$ are coprime, for each $i$; hence
transport acts on rational ideal points in lowest terms.
\end{theorem}

\begin{proof}
Each $T_i$ has determinant $\pm1$, hence is invertible over $\ZZ$ and preserves the
ideal generated by the two entries.
\end{proof}

\begin{theorem}[Parity is a transport invariant]\label{thm:transparity}
For each $i$ and each $(p,q)$, the entries of $T_i(p,q)$ have sum of the same parity
as $p+q$; hence so does $T_w(p,q)$ for every word $w$ in the three maps.
\end{theorem}

\begin{proof}
$(2p-q)+p=3p-q\equiv p+q$, $(2p-q)-p=p-q\equiv p+q$, and $p+(q-2p)=q-p\equiv p+q$,
all modulo $2$.
\end{proof}

\begin{corollary}
No word of Berggren moves transports the $0$-star $(0,1)$ to the $1$-star $(1,1)$ or
conversely: their parameter sums have opposite parities. The visual asymmetry between
the all-charge fan at $0$ and the odd-charge fan at $1$ is intrinsic, not an artefact
of the choice of root.
\end{corollary}

\begin{theorem}[The ladder collapses]\label{thm:ladder}
For every $k\ge0$, $T_1^{\,k}(k,\,k+1)=(0,1)$: the word $B_1^{\,k}$ transports the
star at $k/(k+1)$ onto the $0$-star. Moreover $\gcd(k,k+1)=1$ and $k+(k+1)$ is odd,
so by Theorem~\ref{thm:fan} each ladder star realises every integer charge.
\end{theorem}

\begin{proof}
$T_1(k+1,k+2)=(2(k+1)-(k+2),\,k+1)=(k,\,k+1)$, so one application walks the ladder
down by one rung; induct, terminating at $(0,1)$.
\end{proof}

Thus infinitely many of the visible fans --- those at $1/2,2/3,3/4,4/5,\ldots$
marching towards the ideal point $1$ --- are one single fan seen through different
tree words, all of $0$-type, and none of them is ever a transport of the $1$-star.

\section{Algorithms}

\textbf{A (Charge and ray data).} Given $p/q$ in lowest terms and a seed $(m,n)$,
return the charge $k=pm-qn$, the hypercycle level $\arsinh(|k|/q)$, the Euclidean ray
parameter $k/q$, the approximation error $-k/(qm)$, and the flag $|k|=1$ marking a
Farey neighbour. Constant time.

\smallskip\noindent\textbf{B (Ray enumeration).} Compute $(a,b)$ with $pb-qa=1$ by the
extended Euclidean algorithm; for $s$ from $|ka|+|kb|+|k(b-a)|+1$ upwards, emit
$\Sigma(k,s)=(kb+sq,\ ka+sp)$ whenever the arithmetic test holds --- for $p,q,k$ all
odd this is simply $\gcd(|k|,s)=1$, and in general it is $\gcd(k,s)=1$ together with
the parity of $k(a+b)+s(p+q)$. Cost $O(\log q)$ for the B\'ezout step and
$O(\log|k|)$ per emitted node, versus $O(M)$ for a scan of all seeds.

\smallskip\noindent\textbf{C (Fan classification).} Given $p/q$: return \emph{full} if
$p+q$ is odd, listing the axis node $(q,p)$, and \emph{half} if $p+q$ is even, in
which case the axis is empty and only odd charges occur. Constant time.

\smallskip\noindent\textbf{D (Resolved star centres).} Given $y$ and $\varepsilon$,
set $Q=\lfloor y/\varepsilon\rfloor$ and emit all $p/q$ in lowest terms with
$1\le p\le q\le Q$; the output has $\sum_{q\le Q}\varphi(q)$ elements, computable in
$O(Q\log\log Q)$ by a totient sieve.

\smallskip\noindent\textbf{E (Ray density).} For an odd charge $k$ at an odd/odd
rational, return the exact window count $2\varphi(|k|)$ per $2|k|$ parameters and the
density $\varphi(|k|)/|k|$; the totient costs $O(\sqrt{|k|})$ by trial division.

\smallskip\noindent\textbf{F (Star transport).} Fold $T_1,T_2,T_3$ along a word $w$;
cost $O(|w|)$. The parity of the parameter sum is invariant and gives an $O(1)$
obstruction test before running the fold.

\section{Discussion}

The results assemble into a single statement: the star map is exact. Every straight
line the eye finds in the plot is a hypercycle for a rational ideal point, indexed by
an integral charge; the set of occupied levels is determined by a parity bit; the
population of each level is a totient; the set of levels one can see is a Farey set;
and the tree action permutes the whole system by an integral linear representation on
the star parameter.

The dichotomy of Theorem~\ref{thm:fan} is enforced by an invariant of the tree action
(Theorem~\ref{thm:transparity}), so the classification of fans into full and half is
stable under the entire dynamics; in particular the classical asymmetry between the
$0$-star and the $1$-star is explained. Theorem~\ref{thm:density} says a ray of charge
$k$ has density $\prod_{\ell\mid k}(1-1/\ell)$, which is directly visible: rays of
prime charge look continuous, rays of highly composite charge look dotted. This is the
first place where the arithmetic of the \emph{label} of a ray, rather than of the
nodes on it, becomes geometrically observable. Theorem~\ref{thm:res} converts a
question about seeing into a question about denominators, with the practical
prediction that doubling the plotting resolution approximately quadruples the number
of discernible fans. Finally Theorem~\ref{thm:two} removes the suspicion that the fans
are a sparse decoration on a generic cloud: every node is an innermost-ray node for
two different star centres of smaller denominator, so the star structure is
exhaustive.

That so much is \emph{exactly} computable is a consequence of the transparency of the
embedding: $\Ima z=1/m$ and $\Rea z=n/m$ are the seed coordinates barely disguised, so
hyperbolic invariants become rational functions of $m$ and $n$, and the only
transcendental step is a single $\arsinh$ or $\arcosh$, which monotonicity removes.

\section{Future directions}

\begin{conjecture}[Farey visibility asymptotic]
With $Q=\lfloor y/\varepsilon\rfloor$,
$\#\mathcal{F}(Q)=\sum_{q\le Q}\varphi(q)=\dfrac{3}{\pi^2}Q^2+O(Q\log Q)$.
The reduction from a geometric visibility question to the summatory totient is
complete; what remains is purely analytic. The statement would be the first
quantitative prediction about the picture itself: doubling the resolution quadruples
the number of visible fans. Falsifiable by any enumeration whose ratio
$\#\mathcal{F}(Q)/Q^2$ stabilises away from $3/\pi^2=0.30396\ldots$
\end{conjecture}

\begin{conjecture}[Exact node count on a ray]
On the ray of odd charge $k$ at an odd/odd rational $p/q$, the number of nodes with
first coordinate at most $M$ is
$\dfrac{\varphi(|k|)}{|k|}\cdot\dfrac{M}{q}+O\big(\sigma_0(|k|)+q\big)$.
The window law already gives the exact periodic count, so the only missing ingredient
is the translation from the parameter $s$ to the seed size $m=kb+sq$; the density is
forced and the error term is an edge effect.
\end{conjecture}

Further problems. \emph{Mixed-parity density.} Theorem~\ref{thm:density} assumes $p,q$
both odd; when $p+q$ is odd the parity condition genuinely constrains the parameter and
Theorem~\ref{thm:windows}(2)--(3) predicts counts $\varphi(2|k|)$ or
$2\varphi(|k|)-\varphi(2|k|)$ per window. Numerically the ray of charge $3$ at $1/2$
has density $1/3$ rather than $2/3$, exactly the predicted extra factor of~$2$.
\emph{Equidistribution of charges.} How are the charges at $p/q$ of all seeds with
$m\le M$ distributed? The approximation dictionary suggests a limiting profile
independent of $p/q$ after rescaling by $q$. \emph{Modular interpretation.} The three
moves generate a subgroup of $\mathrm{PGL}_2(\ZZ)$ and the transport action is its
contragredient representation; identifying the congruence subgroup and matching the
parity invariant against its cusps would place the star picture inside modular-curve
geometry, with the two star types appearing as two cusp classes. \emph{Transport
orbits.} Since the parity of $p+q$ is invariant there are at least two orbits of fans;
are there exactly two? \emph{The residual as a height.} The radius of a node is
$\tfrac12\log c$ plus a residual confined to $[0,\tfrac12\log2)$, an explicitly
computable bounded function behaving like a Lyapunov function for the dynamics; is it
a local height in the Arakelov sense?

